import React from 'react';
import Papa from 'papaparse';

const CsvLoader = ({ onLoadData }) => {
  const handleFileLoad = (event, type) => {
    const file = event.target.files[0];
    Papa.parse(file, {
      header: true,
      complete: (result) => {
        onLoadData((prevData) => ({
          ...prevData,
          [type]: result.data
        }));
      }
    });
  };

  return (
    <div>
      <label>
        Load Vehicles CSV:
        <input type="file" accept=".csv" onChange={(e) => handleFileLoad(e, 'vehicles')} />
      </label>
      <br />
      <label>
        Load Stations CSV:
        <input type="file" accept=".csv" onChange={(e) => handleFileLoad(e, 'stations')} />
      </label>
    </div>
  );
};

export default CsvLoader;
